#include <bits/stdc++.h>using namespace std;#define int long longint n,x,y; void O_o(){    cin >> n >> x >> y;    vector<int> a(n + 1);    int sum = 0;    for(int i=1;i<=n;i++){        cin >> a[i];        sum += a[i] / x;    }    int ans = -1;    for(int i=1;i<=n;i++){        ans = max(ans,(sum - a[i] / x) * y + a[i]);    }    cout << ans << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    int T;cin >> T;    while(T--)O_o();    return 0;}